solution.code:
#include <stdio.h>

int main() {
    for (int n = 0; n < 5; n++) {
        int value = 1;
        for (int k = 0; k <= n; k++) {
            printf("%d ", value);
            value = value * (n - k) / (k + 1);
        }
        printf("\n");
    }
    return 0;
}
